(()=>{const cards=[...document.querySelectorAll('[data-guide]')],input=document.getElementById('guide-search');if(!input)return;let area='all';const norm=s=>s.toLowerCase().replace(/[–—-]/g,' ').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();const aliases={mwb:'mini whiteboard',mwbs:'mini whiteboard',cfu:'checking for understanding',eta:'everyone together anyone'};function update(){const terms=norm(input.value).split(' ').filter(Boolean).map(t=>aliases[t]||t);let count=0;cards.forEach(c=>{const hay=norm(c.dataset.search);c.hidden=!((area==='all'||c.dataset.area===area)&&terms.every(t=>hay.includes(t)));if(!c.hidden)count++;});document.getElementById('guide-count').textContent=count+' '+(count===1?'guide':'guides');document.getElementById('guide-empty').hidden=count>0;}input.addEventListener('input',update);document.getElementById('guide-clear').addEventListener('click',()=>{input.value='';update();input.focus();});document.querySelectorAll('[data-guide-filter]').forEach(b=>b.addEventListener('click',()=>{area=b.dataset.guideFilter;document.querySelectorAll('[data-guide-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});update();}));update();})();